#include <array>
#include <fstream>
int main() {
    std::ifstream in("crossroad.in");
    std::ofstream out("crossroad.out");
    std::array<int, 11> last;
    last.fill(-1);
    int n;
    in >> n;
    int answer = 0;
    for (int observation = 0; observation < n; ++observation) {
        int cow, side;
        in >> cow >> side;
        if (last[cow] != -1 && last[cow] != side) ++answer;
        last[cow] = side;
    }
    out << answer << '\n';
}
