#include <array>
#include <fstream>
#include <string>
int main() {
    std::ifstream in("circlecross.in");
    std::ofstream out("circlecross.out");
    std::string word;
    in >> word;
    std::array<int, 26> first, second;
    first.fill(-1);
    for (int index = 0; index < static_cast<int>(word.size()); ++index) {
        const int cow = word[index] - 'A';
        if (first[cow] == -1) first[cow] = index;
        else second[cow] = index;
    }
    int answer = 0;
    for (int a = 0; a < 26; ++a) {
        for (int b = a + 1; b < 26; ++b) {
            const bool firstInside = first[a] < first[b] && first[b] < second[a];
            const bool secondInside = first[a] < second[b] && second[b] < second[a];
            if (firstInside != secondInside) ++answer;
        }
    }
    out << answer << '\n';
}
