#include <algorithm>
#include <fstream>
#include <utility>
#include <vector>
int main() {
    std::ifstream in("cowqueue.in");
    std::ofstream out("cowqueue.out");
    int n;
    in >> n;
    std::vector<std::pair<long long, long long>> cows(n);
    for (auto &cow : cows) in >> cow.first >> cow.second;
    std::sort(cows.begin(), cows.end());
    long long finish = 0;
    for (const auto &cow : cows) finish = std::max(finish, cow.first) + cow.second;
    out << finish << '\n';
}
